const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=v=>v===null||v===undefined?'未知':Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
const time=v=>v?new Date(v).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'尚未同步';
const tone=n=>n>0?'profit':n<0?'loss':'';
const delta=n=>n===null?'初始登记':`${n>0?'+':''}${fmt(n)} · ${n>0?'盈利':n<0?'亏损':'无变化'}`;
export function accountSummary(a){return a?`<span>${esc(a.alias)}${a.status==='disabled'?'（已停用）':''}</span><span>初始 <b>${fmt(a.initialCapital)}</b></span><span>余额 <b>${fmt(a.currentBalance)}</b></span><span class="${tone(a.cumulativePnl)}">累计 ${fmt(a.cumulativePnl)}</span><span class="${tone(a.cumulativePnl)}">比例 ${a.pnlPct==null?'未知':(a.pnlPct*100).toFixed(2)+'%'}</span><span>同步 ${time(a.lastSyncAt)}</span>`:''}
export function accountPanel(a,changes=[],compact=false){if(!a)return'';const content=`<section class="balance-panel" aria-label="账户资金概况"><div class="balance-heading"><h3>账户资金概况</h3><div class="balance-actions">${a.initialCapital==null?`<button type="button" class="secondary" data-account-action="initial">补初始资金</button>`:""}<button type="button" class="secondary" data-account-action="sync">修改实际余额</button><button type="button" class="secondary" data-account-action="add">添加账户</button><button type="button" class="secondary" data-account-action="remove" ${a.isDefault?'disabled title="默认账户受保护"':''}>删除/停用账户</button></div></div><div class="account-summary">${accountSummary(a)}</div><p class="muted">累计为余额与初始资金的差额，含入出金与校准影响；交易净盈亏按执行流水统计。</p>${compact?(compact==='wood'?`<p>本月手动余额变化 <b class="${tone(a.monthlyBalanceChange)}">${fmt(a.monthlyBalanceChange)} 元</b></p>`:''):`<p>本月手动余额变化 <b class="${tone(a.monthlyBalanceChange)}">${fmt(a.monthlyBalanceChange)} 元</b></p><details class="balance-history" open><summary>余额变动记录 · ${changes.length} 条</summary><label class="balance-date">月份 <input type="month" data-balance-month aria-label="余额记录月份"></label><div class="balance-scroll"><table><thead><tr><th>时间（北京）</th><th>修改前</th><th>修改后</th><th>变动金额</th><th>盈亏方向</th><th>来源页面</th><th>备注</th><th>状态</th><th>操作</th></tr></thead><tbody>${changes.length?changes.map(c=>`<tr data-balance-date="${new Date(Date.parse(c.effectiveAt)+8*3600000).toISOString().slice(0,7)}" class="${c.status==='已作废'?'voided':''}"><td>${time(c.effectiveAt)}${c.updatedAt!==c.createdAt?`<br><small>修订 ${time(c.updatedAt)}</small>`:''}</td><td>${fmt(c.beforeBalance)}</td><td>${fmt(c.afterBalance)}</td><td class="${tone(c.amount)}">${c.amount>0?'+':''}${fmt(c.amount)}</td><td>${esc(c.direction)}</td><td>${esc(c.sourcePage)}</td><td title="${esc(c.voidReason||'')}">${esc(c.note)}</td><td>${esc(c.status)}</td><td><button type="button" class="link-button" data-balance-note="${c.id}">备注</button>${c.status!=='已作废'?`<button type="button" class="link-button" data-balance-correct="${c.id}">修正</button><button type="button" class="link-button danger-link" data-balance-void="${c.id}">作废</button>`:''}</td></tr>`).join(''):'<tr><td colspan="9">暂无余额变动记录</td></tr>'}</tbody></table></div></details>`}</section>`;if(!compact)return content;return content.replace('<section class="balance-panel" aria-label="账户资金概况">',`<details class="balance-panel" aria-label="账户资金概况"><summary><strong>${esc(a.alias)} · 最新余额 ${fmt(a.currentBalance)} 元</strong><span>展开账户操作与资金摘要</span></summary>`).replace('</section>','<p><a href="/?view=rules">查看完整余额变动记录</a></p></details>')}

export function createAccountUI({api,getAccount,getChanges=()=>[],onChange,beforeOpen=async()=>{}}){
 const dialog=document.createElement('dialog');dialog.className='account-editor';dialog.id='accountDialog';document.body.append(dialog);
 function form(title,content,submitText,save){
  dialog.innerHTML=`<form><h2>${title}</h2>${content}<p class="account-error" role="alert" hidden></p><div class="account-form-actions"><button type="button" class="secondary" data-cancel>取消</button><button class="primary" type="submit">${submitText}</button></div></form>`;
  const f=dialog.querySelector('form');f.querySelector('[data-cancel]').onclick=()=>dialog.close();let busy=false;
  f.onsubmit=async e=>{e.preventDefault();if(busy||!f.reportValidity())return;busy=true;const submit=f.querySelector('[type=submit]'),error=f.querySelector('[role=alert]');submit.disabled=true;error.hidden=true;try{const result=await save(f);dialog.close();await onChange(result)}catch(e){error.textContent=e.message;error.hidden=false}finally{busy=false;submit.disabled=false}};
  dialog.showModal();return f;
 }
 async function open(action='sync',sourcePage='顶部账户管理',change){
  await beforeOpen();const a=getAccount();if(!a&&action!=='add')return;
  if(action==='add')return form('添加账户',`<label>账户名称<input name="alias" required maxlength="100"></label><label>账户类型<select name="mode"><option value="real">实盘</option><option value="simulation">模拟</option></select></label><label>初始资金（元）<input name="initialCapital" type="number" min="0" step="0.01" required></label><label>当前实际余额（元）<input name="balance" type="number" min="0" step="0.01" required></label><label class="wide">备注<textarea name="note" rows="2"></textarea></label>`,'确认添加',async f=>({action,account:await api('/api/workbench/accounts',{method:'POST',body:JSON.stringify({alias:f.elements.alias.value.trim(),mode:f.elements.mode.value,initialCapital:Number(f.elements.initialCapital.value),equity:Number(f.elements.balance.value),notes:f.elements.note.value,sourcePage})})}));
  if(action==='initial')return form('填写初始资金',`<p class="wide">${esc(a.alias)}。请按本账户真实起始记录填写；当前余额和交易流水保持原值。</p><label class="wide">初始资金（元）<input name="initial" type="number" min="0.01" step="0.01" required></label>`,'确认保存',async f=>({action,account:await api('/api/workbench/accounts',{method:'POST',body:JSON.stringify({...a,initialCapital:Number(f.elements.initial.value),sourcePage})})}));
  if(action==='remove'){
   if(a.isDefault)throw Error('默认账户不能删除或停用');
   return form('确认删除/停用账户',`<p class="wide">账户：${esc(a.alias)}</p><p class="wide">有交易卡、计划或执行记录的账户只停用，历史记录保留。无业务记录的账户删除后仍保留审计快照。</p><label class="wide account-check"><input type="checkbox" required> 我已核对账户名称，确认删除或停用</label>`,'确认删除/停用',async()=>({action,...await api(`/api/workbench/accounts/${a.id}`,{method:'DELETE',body:JSON.stringify({confirmed:true})})}));
  }
  const path=`/api/workbench/accounts/${a.id}/balance-changes/${change?.id}`;
  if(action==='void')return form('作废余额记录',`<p class="wide">${esc(a.alias)} · ${time(change.effectiveAt)} · ${fmt(change.afterBalance)} 元</p><p class="wide">作废后按剩余有效余额和后续交易流水重算，不删除交易记录。后续已有新的绝对余额时，以后续余额为准。</p><label class="wide">作废原因<textarea name="reason" required></textarea></label><label class="wide account-check"><input type="checkbox" required> 确认作废并保留原记录</label>`,'确认作废',async f=>({action,...await api(path+'/void',{method:'POST',body:JSON.stringify({confirmed:true,sourcePage,reason:f.elements.reason.value,expectedRevision:a.revision,updatedAt:change.updatedAt})})}));
  if(action==='note')return form('编辑余额备注',`<label class="wide">备注<textarea name="note" rows="3">${esc(change.note)}</textarea></label>`,'保存备注',async f=>({action,...await api(path,{method:'PATCH',body:JSON.stringify({action:'note',sourcePage,note:f.elements.note.value,updatedAt:change.updatedAt})})}));
  const before=change?change.beforeBalance:a.currentBalance,requestId=crypto.randomUUID();
  const f=form(action==='correct'?'修正余额记录':'手动同步实际余额',`<p class="wide">${esc(a.alias)} · 来源：${esc(sourcePage)}</p><label>修改前余额（元）<input value="${fmt(before)}" readonly></label><label>${change?'修正后':'修改后'}余额（元）<input name="balance" type="number" min="0" step="0.01" value="${esc(change?.afterBalance??a.currentBalance)}" required></label><p class="wide balance-preview" aria-live="polite"></p>${change?'<p class="wide">修正历史绝对余额不会覆盖后续已确认的余额；原值留在审计记录。</p>':''}<label class="wide">用户备注<textarea name="note" rows="2">${esc(change?.note||'')}</textarea></label><p class="wide">手动核对，不连接券商。保存时间为北京时间。</p>`,'确认保存',async f=>({action,...await api(change?path:`/api/workbench/accounts/${a.id}/balance`,{method:change?'PATCH':'POST',body:JSON.stringify({action:'correct',balance:Number(f.elements.balance.value),note:f.elements.note.value,sourcePage,expectedRevision:a.revision,updatedAt:change?.updatedAt,requestId})})}));
  const preview=()=>{const d=before===null?null:Math.round((Number(f.elements.balance.value)-before)*100)/100;f.querySelector('.balance-preview').className='wide balance-preview '+tone(d);f.querySelector('.balance-preview').textContent=`${fmt(before)} → ${fmt(Number(f.elements.balance.value))} 元；${delta(d)}${d===null?'':' 元'}`};f.oninput=preview;preview();
 }
 function bind(root=document,sourcePage='账户管理'){
  const safely=fn=>()=>Promise.resolve().then(fn).catch(e=>{window.alert(e.message)});
  root.querySelectorAll('[data-account-action]').forEach(b=>b.onclick=safely(()=>open(b.dataset.accountAction,sourcePage)));
  for(const action of ['note','correct','void'])root.querySelectorAll(`[data-balance-${action}]`).forEach(b=>b.onclick=safely(()=>open(action,sourcePage,getChanges().find(c=>c.id===b.getAttribute('data-balance-'+action)))));
  root.querySelectorAll('[data-balance-month]').forEach(input=>input.oninput=()=>root.querySelectorAll('[data-balance-date]').forEach(row=>row.hidden=Boolean(input.value&&row.dataset.balanceDate!==input.value)));
 }
 return{open,bind};
}
